<script setup lang="ts">
import {ref,reactive,onMounted,onBeforeUnmount,watch,computed,nextTick} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {useEditor,EditorContent} from '@tiptap/vue-3'
import StarterKit from '@tiptap/starter-kit'
import Image from '@tiptap/extension-image'
import {api,message,notify,genres,type Tag,type Work} from '../api'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter(),id=ref<number|undefined>(route.params.id?Number(route.params.id):undefined),tags=ref<Tag[]>([]),ready=ref(false),published=ref(false),preview=ref(false),busy=ref(false),error=ref(''),saved=ref('尚未保存'),dirty=ref(false)
const form=reactive({title:'',genre:'散文',excerpt:'',cover:'',body:'',tagIds:[] as number[],collectionTags:[] as string[]}),fileInput=ref<HTMLInputElement|null>(null),imageInput=ref<HTMLInputElement|null>(null)
let timer:ReturnType<typeof setTimeout>,pending:Promise<any>|null=null
const editor=useEditor({extensions:[StarterKit.configure({heading:{levels:[2,3]},link:false}),Image],editorProps:{attributes:{'aria-label':'作品正文',class:'prose'}},onUpdate:({editor:e})=>{form.body=e.getHTML();changed()}})
const collectionText=ref('')
watch(collectionText,value=>{form.collectionTags=value.split(/[\n,，]+/).map(n=>n.replace(/^#?合集[：:]/,'').trim()).filter(Boolean)})
const count=computed(()=>editor.value?.getText().replace(/\s/g,'').length||0)
function changed(){if(!ready.value)return;dirty.value=true;clearTimeout(timer);saved.value=published.value?'有未发布的修改':'等待保存…';if(!published.value)timer=setTimeout(()=>{save(false,true)},1800)}
watch(()=>[form.title,form.genre,form.excerpt,form.cover,[...form.tagIds],[...form.collectionTags]],changed,{deep:true})
async function save(publish=false,automatic=false){clearTimeout(timer);if(pending)await pending;if(automatic&&!dirty.value)return;if(automatic&&!form.title&&!count.value)return;busy.value=true;error.value='';const snapshot=JSON.stringify(form);const action=(async()=>{try{const result=id.value?await api.put(`/member/works/${id.value}`,{...form,publish}):await api.post('/member/works',{...form,publish});id.value=result.data.id;dirty.value=JSON.stringify(form)!==snapshot;saved.value=`已保存 · ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`;if(publish){published.value=true;dirty.value=false;notify('作品已发布');router.push(`/work/${id.value}`)}else if(!automatic)notify('草稿已保存')}catch(e){error.value=message(e);saved.value='保存失败，请重试'}finally{busy.value=false;pending=null}})();pending=action;await action}
function toggleTag(tag:number){form.tagIds=form.tagIds.includes(tag)?form.tagIds.filter(t=>t!==tag):[...form.tagIds,tag].slice(0,5)}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(count.value&&!confirm('导入文字将替换当前正文，是否继续？')){input.value='';return}busy.value=true;try{const data=new FormData();data.append('file',file);const result=await api.post('/member/import',data);const escape=(s:string)=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');editor.value?.commands.setContent(result.data.text.split(/\r?\n/).map((p:string)=>`<p>${escape(p)||'<br>'}</p>`).join(''));form.body=editor.value?.getHTML()||'';if(!form.title)form.title=file.name.replace(/\.[^.]+$/,'').slice(0,100);changed();notify('文字已导入，请检查换行与排版')}catch(e){notify(message(e))}finally{busy.value=false;input.value=''}}
async function uploadImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;try{const data=new FormData();data.append('file',file);const result=await api.post('/member/images',data);editor.value?.chain().focus().setImage({src:result.data.url,alt:file.name}).run()}catch(e){notify(message(e))}finally{busy.value=false;input.value=''}}
onMounted(async()=>{try{tags.value=(await api.get('/public/tags')).data;if(id.value){const w:Work=(await api.get(`/public/works/${id.value}`)).data;Object.assign(form,{title:w.title,genre:w.genre,excerpt:w.excerpt,cover:w.cover,body:w.body,tagIds:w.tags.filter(t=>t.kind!=='COLLECTION').map(t=>t.id),collectionTags:w.tags.filter(t=>t.kind==='COLLECTION').map(t=>t.name.replace(/^合集[：:]/,''))});collectionText.value=form.collectionTags.map(n=>'#合集：'+n).join('\n');published.value=w.status==='PUBLISHED';editor.value?.commands.setContent(w.body);saved.value='稿件已载入'}else if(route.query.tag)form.tagIds=[Number(route.query.tag)];await nextTick();ready.value=true}catch(e){error.value=message(e)}})
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',unload)
onBeforeRouteLeave(async()=>{clearTimeout(timer);if(pending)await pending;if(dirty.value&&!published.value)await save(false,true);if(dirty.value)return confirm('仍有未保存的修改，确定离开吗？')})
onBeforeUnmount(()=>{clearTimeout(timer);window.removeEventListener('beforeunload',unload);editor.value?.destroy()})
</script>
<template><div class="container page-space editor-page"><div class="editor-top"><div><p class="eyebrow">投稿 / 编辑</p><h1 class="page-title">编辑作品</h1></div><span class="save-status"><Icon name="Check" :size="14"/>{{saved}}</span></div><p v-if="error" class="error-message" role="alert">{{error}}</p><div class="editor-layout"><section class="editor-paper"><input v-model="form.title" class="title-input" placeholder="作品标题" aria-label="作品标题" maxlength="100" :disabled="!ready"/><div class="editor-toolbar"><template v-if="!preview"><button aria-label="加粗" :class="{selected:editor?.isActive('bold')}" @click="editor?.chain().focus().toggleBold().run()"><Icon name="Bold"/></button><button aria-label="斜体" @click="editor?.chain().focus().toggleItalic().run()"><Icon name="Italic"/></button><button aria-label="小标题" @click="editor?.chain().focus().toggleHeading({level:2}).run()"><Icon name="Heading2"/></button><button aria-label="引用" @click="editor?.chain().focus().toggleBlockquote().run()"><Icon name="Quote"/></button><button aria-label="列表" @click="editor?.chain().focus().toggleBulletList().run()"><Icon name="List"/></button><span class="toolbar-divider"></span><button aria-label="插入图片" :disabled="busy" @click="imageInput?.click()"><Icon name="Image"/></button><button aria-label="撤销" @click="editor?.chain().focus().undo().run()"><Icon name="Undo"/></button></template><button class="preview-toggle" @click="preview=!preview">{{preview?'继续编辑':'阅读预览'}}</button></div><EditorContent v-show="!preview" :editor="editor" class="writing-area"/><div v-if="preview" class="prose preview-area" v-html="form.body"></div><div class="editor-bottom"><span>{{count}} 字</span><span>支持自动保存草稿</span></div></section><aside class="editor-sidebar"><section class="panel"><h3>作品信息</h3><label>体裁<select v-model="form.genre"><option v-for="g in genres.slice(1)" :key="g">{{g}}</option></select></label><label>一小段引言<textarea v-model="form.excerpt" rows="3" maxlength="240" placeholder="留空时将从正文中提取"></textarea></label><label>标签 / 征稿活动</label><div class="tag-choices"><button v-for="t in tags" :key="t.id" :class="{selected:form.tagIds.includes(t.id)}" @click="toggleTag(t.id)"># {{t.name}}</button></div><p class="quiet-note">最多选择 5 个普通标签</p><label>合集标签<textarea v-model="collectionText" rows="3" placeholder="#合集：诗集名称&#10;每行一个，可直接修改"></textarea></label><p class="quiet-note">最多 10 个合集。修改标签会同步更新目录，已有合集保留篇目顺序。</p></section><section class="panel import-panel"><Icon name="Upload"/><h3>导入文档</h3><p>导入 DOCX、文字型 PDF 或 TXT。首版提取正文，图片请另行插入。</p><button class="button secondary full-width" :disabled="busy||!ready" @click="fileInput?.click()">选择文档</button></section><section class="publish-panel"><p>发布后访客可阅读。当前仅进行基础内容检查。</p><button class="button full-width" :disabled="busy||!ready" @click="save(true)"><Icon name="Send" :size="16"/>{{published?'检查并更新发布':'检查并发布'}}</button><button v-if="!published" class="text-button full-width" :disabled="busy||!ready" @click="save(false)">保存为草稿</button></section></aside></div><input ref="fileInput" class="visually-hidden" type="file" accept=".docx,.pdf,.txt" @change="importFile"/><input ref="imageInput" class="visually-hidden" type="file" accept="image/jpeg,image/png" @change="uploadImage"/></div></template>
